module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output              clk_div
);

reg [3:0] cnt;
reg clk_ave_r;
reg clk_adjust_r;
wire [3:0] next_cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) cnt <= 4'd0; else cnt <= next_cnt;
end

assign next_cnt = (cnt == MUL2_DIV_CLK - 1) ? 4'd0 : cnt + 1;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        clk_ave_r <= 1'b0;
    else begin
        case(cnt)
            4'd0, 4'd4: clk_ave_r <= 1'b1;
            default: clk_ave_r <= 1'b0;
        endcase
    end
end

always @(negedge clk or negedge rst_n) begin
    if (!rst_n)
        clk_adjust_r <= 1'b0;
    else begin
        case(cnt)
            4'd1, 4'd4: clk_adjust_r <= 1'b1;
            default: clk_adjust_r <= 1'b0;
        endcase
    end
end

assign clk_div = clk_adjust_r | clk_ave_r;

endmodule
